  // Ronde 131 : les écritures du monde. Si la police d'un système d'écriture manque, le
  // navigateur dessine des carrés. Au lieu de précharger toutes les graisses Noto, on ne
  // recharge que la graisse de la langue ACTUELLE. Le système d'écriture vient d'Intl
  // (sous-étiquettes probables : ja -> Jpan, ar -> Arab, zh-TW -> Hant, hi -> Deva) — il
  // n'a donc pas besoin de table et connaît aussi des langues qui n'ont jamais figuré ici.
  // Inter couvre le latin, le grec et le cyrillique ; tout le reste, cette
  // fonction le récupère une fois depuis Google Fonts (seule la graisse utilisée est chargée,
  // Google livre des fichiers propres à chaque plage de caractères).
  window.SofiaScriptFonts = (function () {
    const FAMILY = {
      Arab: 'Noto Sans Arabic', Hebr: 'Noto Sans Hebrew', Deva: 'Noto Sans Devanagari',
      Beng: 'Noto Sans Bengali', Guru: 'Noto Sans Gurmukhi', Gujr: 'Noto Sans Gujarati',
      Taml: 'Noto Sans Tamil', Telu: 'Noto Sans Telugu', Knda: 'Noto Sans Kannada',
      Mlym: 'Noto Sans Malayalam', Sinh: 'Noto Sans Sinhala', Thai: 'Noto Sans Thai',
      Laoo: 'Noto Sans Lao', Khmr: 'Noto Sans Khmer', Mymr: 'Noto Sans Myanmar',
      Geor: 'Noto Sans Georgian', Armn: 'Noto Sans Armenian', Ethi: 'Noto Sans Ethiopic',
      Hans: 'Noto Sans SC', Hant: 'Noto Sans TC', Jpan: 'Noto Sans JP',
      Kore: 'Noto Sans KR', Hang: 'Noto Sans KR'
    };
    const loaded = Object.create(null);
    function scriptOf(code) {
      try {
        const c = String(code == null ? '' : code).trim();
        if (!c) return '';
        const loc = new Intl.Locale(c);
        return (loc.maximize && loc.maximize().script) || '';
      } catch (e) { return ''; }
    }
    function ensure(code) {
      const script = scriptOf(code);
      const family = FAMILY[script];
      if (!family || loaded[family]) return script;
      loaded[family] = true;
      try {
        const link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = 'https://fonts.googleapis.com/css2?family=' + family.replace(/ /g, '+') + ':wght@400;700&display=swap';
        document.head.appendChild(link);
      } catch (e) {}
      return script;
    }
    return { ensure: ensure, scriptOf: scriptOf, family: function (code) { return FAMILY[scriptOf(code)] || ''; } };
  })();

