        if (App.UI._sourcePopoverDocHandler) { document.removeEventListener('mousedown', App.UI._sourcePopoverDocHandler, true); App.UI._sourcePopoverDocHandler = null; }
        if (App.UI._sourcePopoverKeyHandler) { document.removeEventListener('keydown', App.UI._sourcePopoverKeyHandler, true); App.UI._sourcePopoverKeyHandler = null; }
