      washSpecWords(str, max) {
        try {
          const stop = { te: 1, me: 1, se: 1, le: 1, la: 1, les: 1, lui: 1, leur: 1, qui: 1, que: 1, et: 1, ou: 1, de: 1, du: 1, des: 1, un: 1, une: 1, mon: 1, ton: 1, son: 1, ma: 1, ta: 1, sa: 1, mes: 1, tes: 1, ses: 1, vos: 1, nos: 1, ce: 1, cet: 1, cette: 1 };
          const w = String(str || '').trim().split(/\s+/).filter(x => x && !/\d/.test(x));
          const out = [];
          for (const t of w) {
            if (out.length >= (max || 2)) break;
            if (out.length > 0 && stop[t.toLowerCase()]) break;
            out.push(t);
          }
          return out.join(' ').replace(/[,.;:]+$/g, '');
        } catch (e) { return String(str || '').trim(); }
      },
      async fillMoiFromSettings(overrideInfo) {
        try {
          if (!App.Sheets || !App.Sheets.getSheet || !App.Sheets.saveSheet) return false;
          let info = '';
          try { info = String(overrideInfo != null ? overrideInfo : ((App.State.settings && App.State.settings.userInfo) || '')); } catch (e) {}
          if (!info.trim()) info = '';
          let s = null;
          try { s = await App.Sheets.getSheet('moi'); } catch (e) { return false; }
          if (!s || typeof s !== 'object') return false;
          let changed = false;
          const blank = (v) => v == null || v === '' || v === '?' || v === '—';
          const setk = (k, v) => { if (v && blank(s[k])) { s[k] = v; changed = true; } };
          const setA = (k, v) => { try { if (!s.anatomie || typeof s.anatomie !== 'object' || Array.isArray(s.anatomie)) { s.anatomie = {}; changed = true; } if (v && blank(s.anatomie[k])) { s.anatomie[k] = v; changed = true; } } catch (e) {} };
          const low = info.toLowerCase();
          try {
            const cands = (App.Age && App.Age.people) ? App.Age.people() : [];
            let uname = '';
            try { uname = String((App.State.settings && (App.State.settings.username || App.State.settings.userName)) || '').trim().toLowerCase(); } catch (eU) {}
            // Ronde 872/873 : le nom des réglages passe en premier — fini le nom
            // en dur. Ne remplace jamais un nom déjà renseigné.
            try {
              const setName = String((App.State.settings && (App.State.settings.username || App.State.settings.userName)) || '').trim();
              const curFold = App.Core.foldName(s.nom);
              if (setName && (s.nom === 'Moi' || blank(s.nom) || curFold === 'max' || curFold === 'moi' || curFold === '?')) { s.nom = setName; changed = true; }
            } catch (eSN) {}
            let selfP = null;
            try { selfP = cands.find(function (p) { return uname && String(p.name || '').toLowerCase() === uname; }) || null; } catch (eF) {}
            if (!selfP && cands.length === 1) selfP = cands[0];
            if (selfP) {
              if (selfP.name && (s.nom === 'Moi' || blank(s.nom))) { s.nom = selfP.name; changed = true; }
              if (selfP.age >= 1 && selfP.age <= 120 && blank(s.age)) { s.age = selfP.age; changed = true; }
              if (selfP.sex === 'm' && blank(s.genre)) { s.genre = 'masculin'; changed = true; }
              else if (selfP.sex === 'f' && blank(s.genre)) { s.genre = 'féminin'; changed = true; }
            }
          } catch (eP) {}
          let m;
          if ((m = low.match(/(\d{2,3})\s*cm(?!\s*x)/))) { const cm = Number(m[1]); if (cm >= 100 && cm <= 250) setk('taille', Math.floor(cm / 100) + ',' + String(cm % 100).padStart(2, '0') + ' m'); }
          if ((m = low.match(/(\d{2,3})\s*(kg|kilos?)\b/))) { const kg = Number(m[1]); if (kg >= 25 && kg <= 350) setk('poids', kg); }
          if (/cr[âa]ne ras[ée]/i.test(info)) setk('cheveux', 'crâne rasé');
          else if ((m = info.match(/cheveux\s+([^,;.\n]{2,60})/i))) setk('cheveux', App.Core.washSpecWords(m[1], 3));
          if ((m = info.match(/yeux\s+([^,;.\n]{2,40})/i))) setk('yeux', App.Core.washSpecWords(m[1], 2));
          if (/aucune barbe/i.test(info)) setA('barbe', 'aucune');
          if (/\bsvelte\b/i.test(low)) setA('silhouette', 'svelte');
          else if ((m = low.match(/\b(athl[ée]tique|muscl[ée]|corpulent|plantureux|rond)/))) setA('silhouette', m[1]);
          if (/bite|p[ée]nis|queue|\bverge\b/i.test(low)) setA('sexe', 'pénis');
          if ((m = low.match(/(\d{1,2})\s*cm\s*x\s*(\d{1,2})\s*cm/))) setA('sexe_taille', m[1] + ' cm x ' + m[2] + ' cm');
          if (/non circoncis/i.test(low)) setA('circoncision', 'non circoncis');
          else if (/circoncis/i.test(low)) setA('circoncision', 'circoncis');
          if (/couilles? ras[ée]es?|pubis ras[ée]|intime ras[ée]/i.test(low)) setA('pilosite', 'rasé');
          if ((m = info.match(/frein[^,;.\n]{0,140}/i))) setA('frein', m[0].trim());
          if ((m = info.match(/petits boutons blancs[^,;.\n]{0,140}/i))) setA('gland', m[0].trim());
          if ((m = info.match(/couilles?[^,;.\n]{0,140}/gi))) setA('testicules', m.map(x => x.trim()).join('; '));
          if ((m = low.match(/(\d{1,3})\s*ans\b/))) { const ag = Number(m[1]); if (ag >= 18 && ag <= 120) setk('age', ag); }
          if (blank(s.genre) && /bite|p[ée]nis|masculin|\bhomme\b/i.test(low)) { s.genre = 'masculin'; changed = true; }
          if (/masculin/i.test(String(s.genre || '')) && blank(s.anatomie && s.anatomie.poitrine)) { try { s.anatomie.poitrine = 'plate'; changed = true; } catch (e) {} }
          if (Array.isArray(s.objets_portes)) {
            for (const o of s.objets_portes) {
              if (o && typeof o === 'object' && o.zone) {
                if (o.endroit == null || o.endroit === 'undefined' || o.endroit === '') { o.endroit = o.zone; changed = true; }
                if (o.emplacement == null || o.emplacement === 'undefined' || o.emplacement === '') { o.emplacement = o.zone; changed = true; }
              }
            }
          }
          if (changed) {
            try {
              if (App.Sheets.saveSheet.length >= 2) await App.Sheets.saveSheet('moi', s);
              else await App.Sheets.saveSheet(s);
            } catch (e) { return false; }
          }
          return changed;
        } catch (e) { return false; }
      },
