        if (ctx.botId) { try { App.UI.setActivityStatus(ctx.botId, 'vision', true); } catch (e) {} }
        let blob = null, observation = '';
        try { blob = await this.visionBlobFor(step.target, step.url); } catch (e) { blob = null; }
