            if (!blob) return;
            let q = "Describe what is REALLY in this picture, in one short paragraph, only what is visible: who is there, what they are doing, where they are, what clothes (if any) they wear or that they are fully clothed, and whether it looks like a real photograph or a drawing, an illustration or a diagram. Do not invent anything that is not visible.";
            let obs = await self.visionLook(blob, q);
