      // Ronde 196 : la même correction, mais LIVE pendant le streaming — la bulle n'affiche
      // jamais « ma queue » (la ronde 147 fait exactement cela pour l'anatomie de l'adresse). Et un
      // mot commencé à la fin est retenu jusqu'à ce qu'il soit complet,
      // pour qu'aucun demi « ma que… » ne clignote puis ne saute.
      clipHerBody(text) {
        let s = String(text == null ? '' : text);
        try { s = this.herBodyRepair(s); } catch (e) { return s; }
        try {
          let m = s.match(/(^|[^a-zà-ÿA-ZÀ-Ý])((?:ma|mon|mes)(?: [a-zà-ÿ]{0,12})?)$/);
          if (m) {
            let tail = String(m[2]).toLowerCase();
            let after = tail.replace(/^(ma|mon|mes)\s*/, '');
            let heads = this._herBodyWordHeads();
            if (!after || heads.some(function (w) { return w.indexOf(after) === 0; })) s = s.slice(0, s.length - m[2].length);
          }
        } catch (e) {}
        return s;
      },

      // Débuts de mots retenus pendant le streaming (voir clipHerBody) :
      // les substantifs qu'elle ne doit jamais employer pour elle, et les adjectifs qui
