          let out = s.replace(new RegExp('(ma|mon) ' + adj + '?(?:queue|verge|bite|p[ée]nis|membre|gland|chibre|pr[ée]puce|scrotum|zob)', 'g'), cap('mon gode ceinture'));
          out = out.replace(/(ma|mon) (sperme|semence|foutre)/g, cap('ma cyprine'));
          out = out.replace(/(ma|la) prostate/g, cap('mon bas-ventre'));
