        return s.replace(re, function (m, a, pre, post) {
          let a2 = art;
          if (a.charAt(0) === a.charAt(0).toUpperCase() && a.charAt(0) !== a.charAt(0).toLowerCase()) a2 = art.charAt(0).toUpperCase() + art.slice(1);
          return a2 + pre + repl + post;
        });
