        // féminin : « ma vulve », jamais « mon vulva ». Vaut pour LES DEUX personnes, donc aussi
        // pour le propre discours de Sofia.
        if (lang === 'fr') {
          s = s.replace(/\b(mon|ton|son)(\s+\*{0,2})(vulves?|vulvas?)\b/gi, function (m, a, pre) {
            let low = a.toLowerCase();
            let repl = (low === 'mon') ? 'ma' : (low === 'ton' ? 'ta' : 'sa');
            if (a.charAt(0) === a.charAt(0).toUpperCase() && a.charAt(0) !== a.charAt(0).toLowerCase()) repl = repl.charAt(0).toUpperCase() + repl.slice(1);
            return repl + pre + 'vulve';
          });
          s = s.replace(/\bvulvas\b/gi, function (m) { return (m.charAt(0) === m.charAt(0).toUpperCase() && m.charAt(0) !== m.charAt(0).toLowerCase()) ? 'Vulves' : 'vulves'; });
          s = s.replace(/\bvulva\b/gi, function (m) { return (m.charAt(0) === m.charAt(0).toUpperCase() && m.charAt(0) !== m.charAt(0).toLowerCase()) ? 'Vulve' : 'vulve'; });
        }
