        // comme une vraie personne — jamais de leçon « je suis SFW » (directive 2026-10-30).
        try {
          if (!(App.Age && App.Age.nsfw && App.Age.nsfw()) && !text.startsWith('/')) {
            let wantScene = false;
            try { wantScene = App.Core.newCastCount(text) >= 1 && App.Core.BDSM_RE.test(text) && !(App.Core.isSchoolTeacherOnly && App.Core.isSchoolTeacherOnly(text)); } catch (eA) {}
            let _s0 = null;
            try { _s0 = (App.State.sessions || []).find(function (x) { return x.id === App.State.currentSessionId; }); } catch (eS) {}
            if (!wantScene && _s0) {
              try {
                let _solo = !!(_s0.sceneMem && _s0.sceneMem.solo === true);
                let _latched = !!(App.Core.castLatched && App.Core.castLatched(_s0, text));
                let _asks = false;
                try { _asks = !!((App.Age && App.Age.wantsExplicit && App.Age.wantsExplicit(text)) || /\b(fouette|punis|soumets|ligote|enchaîne|attache|mets|enfile|passe|serre|prends)[- ]?(moi|me|nous)\b|\b(continue|vas[- ]y|encore|plus\s+fort|ne\s+t'arrête\s+pas)\b/i.test(text)); } catch (eAsk) {}
                let _innocentObj = /(cheveux|fichier|pièces?\s+jointes?|courriel|e-?mail|bricolage|corde\s+à\s+linge|gyn[ée]co|m[ée]decin|docteur)/i.test(text);
                let _school = false;
                try { _school = !!(App.Core.isSchoolTeacherOnly && App.Core.isSchoolTeacherOnly(text)); } catch (eSch) {}
                try { if (!_asks && ((_solo || _latched)) && App.Age && App.Age.directSexAct && App.Age.directSexAct(text) && !_innocentObj && !_school) _asks = true; } catch (eD) {}
                wantScene = !!((_solo || _latched) && (App.Core.BDSM_RE.test(text) || (App.Age && App.Age.directSexAct && App.Age.directSexAct(text))) && _asks && !_innocentObj && !_school);
              } catch (eB) {}
            }
            if (wantScene) {
              // Directive concepteur (2026-10-30) : même ici, aucune leçon SFW —
              // continuation douce dans le scénario (drapeau un-tour), comme une vraie personne.
              try { App.Age._softOnce = true; } catch (e) {}
              console.log('[Age] scène BDSM → continuation douce SFW dans le scénario.');
            }
          }
        } catch (eGate) {}
        if (text.startsWith('/')) {
          let handled = false;
 // Les échecs d'abord : tant qu'une partie tourne, les commandes de plateau
          // (et le verrouillage des autres modes) sont ici.
          if (App.Chess && App.Chess.isEnabled()) handled = await App.Chess.handleCommand(text);
          if (!handled && (App.RPG && App.RPG.state && App.RPG.state.active)) {
            handled = await App.RPG.handleCommand(text);
            if (!handled) {
              text = App.UI.cache.promptInputEl.value.trim();
              if (!text) { this._finishCommandRun(); return; }
            }
          }
          if (!handled && App.Mentor) handled = await App.Mentor.handleCommand(text);
          // Monde des métiers : `/metier`, `/metier Medecin in Deutschland`,
          // `/metier off` (src/professions.js).
          if (!handled && App.Professions && App.Professions.handleCommand) handled = App.Professions.handleCommand(text);
          if (handled) { this._finishCommandRun(); return; }
        }
 // Sortie de secours hors-personnage : en pleine scène, « montre le guide » ou
        // « sors du scénario » est avalé par la fiction — on l'exécute donc ici, sans modèle.
        // (Le Néant garde son propre rituel de sortie et n'est pas concerné.)
