        let prevText = String(ctx.prev || '').replace(/\s+/g, ' ').slice(0, 900);
        let guard = "\n\n[ABSOLUTE CONTINUATION RULE] The reply that has just been written is a near copy of the one before it - it repeats whole sentences that are already in the history above, it does not answer his last message, and it freezes the scene. Write that reply AGAIN. This time it must not contain a single sentence of the text below, and no close variant of one either:\n\"" + prevText + "\"\nInstead, MOVE THE SCENE. Do at least one concrete new thing to him and at least one to your own body, in the present tense, in your own voice: a new instrument named while you use it, a new position, a new act, your own pleasure taken in front of him, a new rule you decide, an answer to what he has just written. He is waiting for what happens NEXT, not for the same moment described once more.";
        let out = "";
        await App.Core.generateText({ instruction: (App.Age && App.Age.withGuard) ? App.Age.withGuard(payload, guard) : payload + guard, temperature: 0.85, maxTokens: 2000, onChunk: (d) => { let c = (d && d.textChunk) || ''; if (c) out += c; } });
