                      try { if (turnSceneLocked && botTextBufferObj && botTextBufferObj.value) { let bvv = String(botTextBufferObj.value); let fns = []; let mm2 = null; let rx2 = /^([A-ZÀ-Þ][A-Za-zÀ-ÿ'’-]{2,})\s*:/gm; while ((mm2 = rx2.exec(bvv))) { let cnn = mm2[1]; if (cnn && !/^(Sofia|Moi|Lui|Elle|Ils|Elles|Nous|Vous|On|Photo|Image)$/i.test(cnn) && !(App.Core.isSofiaName && App.Core.isSofiaName(cnn)) && fns.indexOf(cnn) < 0) fns.push(cnn); } let jm = bvv.match(/je\s+m'appelle\s+([A-ZÀ-Þ][a-zà-ÿ'’-]{2,})/i); if (jm && jm[1] && fns.indexOf(jm[1]) < 0) fns.unshift(jm[1]); if (fns.length && App.Core.castRemember) { try { App.Core.castRemember(session, fns.slice(0, 4)); } catch (eCR) {} } } } catch (eLatch) {}
                      try { if (App.UI && App.UI.refreshThinkingLabel) App.UI.refreshThinkingLabel(botId); } catch (eRL) {}
