        if (s.indexOf('[SOFIA_') === -1 && s.indexOf('[WARDROBE_CUSTOM]') === -1 && s.indexOf('[END_WARDROBE_CUSTOM]') === -1 && s.indexOf('[FICHE_STATE]') === -1 && s.indexOf('[END_FICHE_STATE]') === -1 && s.indexOf('[FICHE]') === -1 && s.indexOf('[/FICHE]') === -1 && s.indexOf('[END_SOFIA_SCENE]') === -1 && !/\[(FICHE_ST[A-Z_]*|END_FICHE_ST[A-Z_]*|END_SOFIA_SC[A-Z_]*|WARDROBE_CUST[A-Z_]*|END_WARDROBE_CUST[A-Z_]*)$/.test(s)) return s;
        let markers = ['[SOFIA_CODE]', '[SOFIA_PY]', '[SOFIA_IMAGE]', '[SOFIA_PHOTO]', '[SOFIA_LOGO]', '[SOFIA_REPRO]', '[SOFIA_VISION]', '[SOFIA_FILEREAD]', '[SOFIA_WEBIMG]', '[SOFIA_WEBSEARCH]', '[SOFIA_FACTCHECK]', '[SOFIA_OPENPAGE]', '[SOFIA_SCRIPT]', '[SOFIA_LEARN]', '[SOFIA_HELPER]', '[SOFIA_EDIT]', '[SOFIA_WORKSHOP]', '[ATELIER]', '[SOFIA_UPDATE]', '[SOFIA_SCENE]', '[WARDROBE_CUSTOM]', '[END_WARDROBE_CUSTOM]', '[FICHE_STATE]', '[END_FICHE_STATE]', '[FICHE]', '[/FICHE]', '[END_SOFIA_SCENE]'];
